LCS backtrack:

```go
func diffOps(a, b []string) []op {
	m, n := len(a), len(b)
	// dp[i][j] = LCS length of a[i:], b[j:]
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	for i := m - 1; i >= 0; i-- {
		for j := n - 1; j >= 0; j-- {
			if a[i] == b[j] {
				dp[i][j] = dp[i+1][j+1] + 1
			} else if dp[i+1][j] >= dp[i][j+1] {
				dp[i][j] = dp[i+1][j]
			} else {
				dp[i][j] = dp[i][j+1]
			}
		}
	}
	var ops []op
	i, j := 0, 0
	for i < m && j < n {
		if a[i] == b[j] {
			ops = append(ops, op{opEqual, a[i]})
			i++
			j++
		} else if dp[i+1][j] >= dp[i][j+1] {
			ops = append(ops, op{opDel, a[i]})
			i++
		} else {
			ops = append(ops, op{opIns, b[j]})
			j++
		}
	}
	for ; i < m; i++ {
		ops = append(ops, op{opDel, a[i]})
	}
	for ; j < n; j++ {
		ops = append(ops, op{opIns, b[j]})
	}
	return ops
}
```

