Let me write grouping adapted to opcodes:

```go
func groupOpCodes(codes []opCode, n int) [][]opCode {
	if len(codes) == 0 {
		codes = []opCode{{'e', 0, 1, 0, 1}}
	}
	// trim leading/trailing equal
	if codes[0].tag == 'e' {
		c := codes[0]
		codes[0] = opCode{'e', max(c.i1, c.i2-n), c.i2, max(c.j1, c.j2-n), c.j2}
	}
	if codes[len(codes)-1].tag == 'e' {
		c := codes[len(codes)-1]
		codes[len(codes)-1] = opCode{'e', c.i1, min(c.i2, c.i1+n), c.j1, min(c.j2, c.j1+n)}
	}
	nn := 2 * n
	var groups [][]opCode
	var group []opCode
	for _, c := range codes {
		if c.tag == 'e' && c.i2-c.i1 > nn {
			group = append(group, opCode{'e', c.i1, min(c.i2, c.i1+n), c.j1, min(c.j2, c.j1+n)})
			groups = append(groups, group)
			group = nil
			c.i1 = max(c.i1, c.i2-n)
			c.j1 = max(c.j1, c.j2-n)
		}
		group = append(group, c)
	}
	if len(group) > 0 && !(len(group) == 1 && group[0].tag == 'e') {
		groups = append(groups, group)
	}
	return groups
}
```

