func lineOpcodes(a, b []string) []opCode {
	m, n := len(a), len(b)
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	for i := m - 1; i >= 0; i-- {
		for j := n - 1; j >= 0; j-- {
			switch {
			case a[i] == b[j]:
				dp[i][j] = dp[i+1][j+1] + 1
			case dp[i+1][j] >= dp[i][j+1]:
				dp[i][j] = dp[i+1][j]
			default:
				dp[i][j] = dp[i][j+1]
			}
		}
	}

	var ops []opCode
	i, j := 0, 0
	for i < m && j < n {
		switch {
		case a[i] == b[j]:
			ops = append(ops, opCode{'e', i, i + 1, j, j + 1})
			i++
			j++
		case dp[i+1][j] >= dp[i][j+1]:
			ops = append(ops, opCode{'d', i, i + 1, j, j})
			i++
		default:
			ops = append(ops, opCode{'i', i, i, j, j + 1})
			j++
		}
	}
	for ; i < m; i++ {
		ops = append(ops, opCode{'d', i, i + 1, j, j})
	}
	for ; j < n; j++ {
		ops = append(ops, opCode{'i', i, i, j, j + 1})
	}
	return coalesce(ops)
}
```

Now coalesce merges consecutive single-line opcodes of the same tag into ranges, and merges adjacent 'd' then 'i' into 'r'. Let me write:

```go
func coalesce(ops []opCode) []opCode {
	var out []opCode
	for _, c := range ops {
		if len(out) == 0 {
			out = append(out, c)
			continue
		}
		last := &out[len(out)-1]
		if last.tag == c.tag && last.i2 == c.i1 && last.j2 == c.j1 && c.tag != 'r' {
			last.i2 = c.i2
			last.j2 = c.j2
			continue
		}
		// merge delete followed by insert into replace
		if last.tag == 'd' && c.tag == 'i' && last.i2 == c.i1 && last.j2 == c.j1 {
			last.tag = 'r'
			last.i2 = c.i2
			last.j2 = c.j2
			continue
		}
		out = append(out, c)
	}
	return out
}
```

