```go
func group(codes []opCode, n int) [][]opCode {
	if len(codes) == 0 {
		return nil
	}
	codes = append([]opCode(nil), codes...) // copy since we mutate
	if codes[0].tag == 'e' {
		c := codes[0]
		codes[0] = opCode{'e', max(c.i1, c.i2-n), c.i2, max(c.j1, c.j2-n), c.j2}
	}
	if last := len(codes) - 1; codes[last].tag == 'e' {
		c := codes[last]
		codes[last] = opCode{'e', c.i1, min(c.i2, c.i1+n), c.j1, min(c.j2, c.j1+n)}
	}
	nn := 2 * n
	var groups [][]opCode
	var cur []opCode
	for _, c := range codes {
		if c.tag == 'e' && c.i2-c.i1 > nn {
			cur = append(cur, opCode{'e', c.i1, min(c.i2, c.i1+n), c.j1, min(c.j2, c.j1+n)})
			groups = append(groups, cur)
			cur = nil
			c.i1 = max(c.i1, c.i2-n)
			c.j1 = max(c.j1, c.j2-n)
		}
		cur = append(cur, c)
	}
	if len(cur) > 0 && !(len(cur) == 1 && cur[0].tag == 'e') {
		groups = append(groups, cur)
	}
	return groups
}
