func applyDiff(al []string, diff string) []string {
	var out []string
	for _, line := range strings.Split(strings.TrimSuffix(diff, "\n"), "\n") {
		if line == "" {
			// could be a blank context line rendered as " " not "". skip empties.
			continue
		}
		switch line[0] {
		case '-', '+':
			// header lines start with "---"/"+++"
			if strings.HasPrefix(line, "---") || strings.HasPrefix(line, "+++") {
				continue
			}
		}
		switch line[0] {
		case ' ':
			out = append(out, line[1:])
		case '+':
			out = append(out, line[1:])
		case '-':
			// drop
		case '@':
			// hunk header
		default:
			// shouldn't happen
		}
	}
	return out
}
